css:
@page {
    size: A4;
    margin: 1.2cm;
}

.rf-rental-agreement {
    width: 100%;
    margin: 0;
    padding: 0;
    color: #222;
    font-size: 11px;
    line-height: 1.4;
}

.rf-header {
    width: 100%;
    text-align: center;
    padding-top: 8px;
    margin-bottom: 14px;
}

.rf-header h1 {
    margin: 0 0 4px 0;
    font-size: 22px;
    font-weight: 600;
}

.rf-header h2 {
    margin: 0 0 4px 0;
    font-size: 16px;
    font-weight: 600;
}

.rf-header p {
    margin: 0;
    font-size: 10px;
    font-weight: 400;
}

.rf-divider {
    margin: 10px 0 16px 0;
    border: 0;
    border-top: 1px solid #d8d8d8;
}

.rf-rental-agreement h3 {
    margin: 14px 0 7px 0;
    font-size: 13px;
    font-weight: 600;
}

/* Customer Details + Rental Period */

.rf-details-table {
    width: 100% !important;
    border-collapse: collapse !important;
    table-layout: fixed;
    margin: 0 0 12px 0;
    border: 1px solid #e5e5e5 !important;
}

.rf-details-table tr {
    height: 34px;
}

.rf-details-table td {
    border: 1px solid #eeeeee !important;
    padding: 7px 10px !important;
    margin: 0 !important;
    vertical-align: middle !important;
    background: #fff !important;
    display: table-cell !important;
}

.rf-details-label {
    width: 30% !important;
    font-size: 11px !important;
    font-weight: 500 !important;
    color: #444 !important;
    background: #fafafa !important;
}

.rf-details-value {
    width: 70% !important;
    font-size: 12px !important;
    font-weight: 400 !important;
    color: #111 !important;
}

/* Rental Items */

.rf-items-table {
    width: 100% !important;
    border-collapse: collapse !important;
    table-layout: fixed;
    margin: 0 0 12px 0;
    border: 1px solid #d8d8d8 !important;
}

.rf-items-table th,
.rf-items-table td {
    border: 1px solid #dddddd !important;
    padding: 6px !important;
    vertical-align: middle !important;
    word-wrap: break-word;
    overflow-wrap: break-word;
}

.rf-items-table th {
    background: #f7f7f7 !important;
    font-size: 10px;
    font-weight: 600;
    text-align: center;
}

.rf-items-table td {
    font-size: 10px;
    font-weight: 400;
}

.rf-items-table th:nth-child(1),
.rf-items-table td:nth-child(1) {
    width: 17%;
}

.rf-items-table th:nth-child(2),
.rf-items-table td:nth-child(2) {
    width: 19%;
}

.rf-items-table th:nth-child(3),
.rf-items-table td:nth-child(3) {
    width: 16%;
}

.rf-items-table th:nth-child(4),
.rf-items-table td:nth-child(4) {
    width: 10%;
}

.rf-items-table th:nth-child(5),
.rf-items-table td:nth-child(5) {
    width: 19%;
}

.rf-items-table th:nth-child(6),
.rf-items-table td:nth-child(6) {
    width: 19%;
}

.rf-center {
    text-align: center !important;
}

/* Payment */

.rf-payment-table {
    width: 100% !important;
    border-collapse: collapse !important;
    margin: 0;
}

.rf-payment-table td {
    padding: 6px 10px !important;
    font-size: 11px !important;
    border: 0 !important;
}

.rf-payment-table td:first-child {
    width: 50%;
    font-weight: 500;
}

.rf-payment-table td:last-child {
    width: 50%;
    text-align: right;
    font-weight: 400;
}

/* Damage Banner */

.rf-damage-banner {
    margin-top: 10px;
    padding: 7px;
    border: 1px solid #d5d5d5;
    text-align: center;
    font-size: 10px;
    font-weight: 600;
}

/* Final Amount */

.rf-final-box {
    width: 100% !important;
    box-sizing: border-box;
    margin-top: 16px;
    padding: 10px 14px !important;
    border: 1px solid #b8b8b8 !important;
    background: #fafafa !important;
    display: flex !important;
    justify-content: space-between !important;
    align-items: center !important;
}

.rf-final-label {
    font-size: 14px !important;
    font-weight: 600 !important;
}

.rf-final-value {
    font-size: 15px !important;
    font-weight: 600 !important;
}

/* Signatures */

.rf-signature-table {
    width: 100% !important;
    border-collapse: collapse !important;
    margin-top: 45px;
}

.rf-signature-table td {
    width: 50%;
    border: 0 !important;
    padding: 5px 10px !important;
    vertical-align: bottom;
}

.rf-signature-title {
    font-size: 10px;
    font-weight: 500;
}

.rf-signature-line {
    width: 75%;
    margin-top: 25px;
    border-bottom: 1px solid #999;
}

/* Print */

@media print {
    .btn,
    .btn-group,
    .print-button {
        display: none !important;
    }

    .rf-items-table tr {
        page-break-inside: avoid;
    }

    .rf-final-box {
        page-break-inside: avoid;
    }

    .rf-signature-table {
        page-break-inside: avoid;
    }
}
